# Pinout D-SUB 26 am Heatend

```{tikz}
#| label: fig-dsub-tikz
#| fig-cap: "Technische Skizze eines D-Sub 9 Steckers mit TikZ"
#| engine: tikz
\begin{tikzpicture}[scale=0.8, every node/.style={transform shape}]

    % 1. Äußere Gehäuse-Lasche / Befestigungsohren (grau)
    \draw[fill=gray!20, draw=gray!80, thick, rounded corners=4pt] 
        (-4.5, -1.8) rectangle (4.5, 1.8);

    % Befestigungslöcher links und rechts (Schraublöcher)
    \draw[fill=white, draw=gray] (-3.7, 0) circle (0.35);
    \draw[fill=white, draw=gray] (3.7, 0) circle (0.35);

    \draw[fill=gray!40, draw=gray] (-3.7, 0) circle (0.15);
    \draw[fill=gray!40, draw=gray] (3.7, 0) circle (0.15);

    % 2. Der charakteristische D-Sub Trapez-Kragen (Metallkragen)
    % Koordinaten spiegeln die typische D-Form wider
    \draw[fill=gray!10, draw=black, name path=kragen, line width=1.2pt] 
        (-2.6,  1.1) -- (2.6,  1.1) -- 
        ( 2.2, -1.1) -- (-2.2, -1.1) -- cycle;

    % 3. Innerer Isolator (Kunststoffträger für die Pins)
    \draw[fill=black!85, draw=black, rounded corners=2pt] 
        (-2.4,  0.9) -- (2.4,  0.9) -- 
        ( 2.0, -0.9) -- (-2.0, -0.9) -- cycle;

    % 4. Pins einzeichnen (Goldene Kreise mit Pin-Nummern)
    % Reihe 1: 5 Pins oben (Pin 1 bis 5)
    \foreach \x/\n in {-1.6/1, -0.8/2, 0.0/3, 0.8/4, 1.6/5} {
        \draw[fill=yellow!80!orange, draw=orange!80!black, thick] (\x, 0.4) circle (0.18);
        \node[text=black, font=\tiny\sffamily\bfseries] at (\x, 0.4) {\n};
    }

    % Reihe 2: 4 Pins unten (Pin 6 bis 9, versetzt angeordnet)
    \foreach \x/\n in {-1.2/6, -0.4/7, 0.4/8, 1.2/9} {
        \draw[fill=yellow!80!orange, draw=orange!80!black, thick] (\x, -0.4) circle (0.18);
        \node[text=black, font=\tiny\sffamily\bfseries] at (\x, -0.4) {\n};
    }

\end{tikzpicture}
```



